def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if value is None:
        return None
    try:
        return value.total_seconds()
    except AttributeError:
        return None

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    return value.strftime("%H:%M:%S")

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    return list(self._data.keys())

def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple or None")

        handlers = {}
        for name, obj in inspect.getmembers(cls):
            if inspect.isclass(obj) and issubclass(obj, cls) and obj is not cls:
                if hasattr(obj, 'protocol_version'):
                    version = obj.protocol_version
                    if protocol_version is None or version == protocol_version:
                        handlers[version] = obj
        return handlers

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._index.index(key)
    except ValueError:
        raise KeyError(key)

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if not keys:
        return list(self._values)
    else:
        return [self._values[key] for key in keys]

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    if not keys:
        return dict(zip(self._keys, self._values))
    result = {}
    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(self._keys):
                raise IndexError("index out of range")
            result[self._keys[key]] = self._values[key]
        else:
            if key in self._keys:
                idx = self._keys.index(key)
                result[key] = self._values[idx]
            else:
                result[key] = None
    return result

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    if len(self.data) < 2:
        raise ValueError("Not enough data to pop 2 bytes")
    data = self.data[-2:]
    self.data = self.data[:-2]
    return int.from_bytes(data, byteorder='big')

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    # Build the class namespace
    namespace = {}

    # Add the fields as class attributes or properties
    for field_name in fields:
        # Create a property for each field
        def make_property(field_name):
            def getter(self):
                return self._data.get(field_name)
            def setter(self, value):
                self._data[field_name] = value
            return property(getter, setter)

        namespace[field_name] = make_property(field_name)

    # Add the srid attribute
    namespace['srid'] = property(lambda self: self._srid, lambda self, value: setattr(self, '_srid', value))

    # Create the class
    PointSubclass = type(name, (Point,), namespace)

    # Set the srid_map as a class attribute
    PointSubclass.srid_map = srid_map

    return PointSubclass

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError("Input must be a string")

    parts = []
    for part in s.split('.'):
        # Extract leading digits from each part
        num_str = ''
        for char in part:
            if char.isdigit():
                num_str += char
            else:
                break
        if num_str:
            parts.append(int(num_str))
        else:
            parts.append(0)

    return tuple(parts)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def decorator(func):
        cache = {}
        order = []

        def wrapper(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items())))
            if typed:
                key = (key, tuple(type(a) for a in args))

            if key in cache:
                # Move to end to mark as most recently used
                if key in order:
                    order.remove(key)
                order.append(key)
                return cache[key]

            result = func(*args, **kwargs)

            # Add to cache
            cache[key] = result
            order.append(key)

            # Evict least recently used if over maxsize
            while len(order) > maxsize:
                lru_key = order.pop(0)
                if lru_key in cache:
                    del cache[lru_key]

            return result

        wrapper.cache_info = lambda: {"hits": 0, "misses": 0, "size": len(cache), "maxsize": maxsize}
        wrapper.cache_clear = lambda: (cache.clear(), order.clear())
        return wrapper
    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    if maxsize is None or maxsize == 0:
        return lambda f: f

    if not isinstance(maxsize, int):
        raise TypeError("Expected maxsize to be an integer or None")

    if maxsize < 0:
        raise ValueError("Expected maxsize to be non-negative")

    def decorator(func):
        cache = {}
        order = []
        lock = None  # No lock for simplicity, but could be added for thread safety

        def wrapper(*args, **kwargs):
            nonlocal cache, order
            key = (args, tuple(sorted(kwargs.items()))) if not typed else (args, tuple(sorted(kwargs.items())), tuple(type(a) for a in args))
            if key in cache:
                # Move to end of order list (most recently used)
                order.remove(key)
                order.append(key)
                return cache[key]
            else:
                result = func(*args, **kwargs)
                cache[key] = result
                order.append(key)
                if len(order) > maxsize:
                    oldest_key = order.pop(0)
                    del cache[oldest_key]
                return result

        wrapper.cache_info = lambda: {"hits": 0, "misses": 0, "maxsize": maxsize, "currsize": len(cache)}
        wrapper.cache_clear = lambda: (cache.clear(), order.clear())
        return wrapper

    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        cache = {}
        freq = {}
        min_freq = 0

        def wrapper(*args, **kwargs):
            nonlocal min_freq
            key = (args, tuple(sorted(kwargs.items())))
            if typed:
                key = (key, tuple(type(a) for a in args))
            if key in cache:
                freq[key] += 1
                return cache[key]
            result = func(*args, **kwargs)
            if len(cache) >= maxsize:
                # Find the key with the minimum frequency
                min_freq_key = None
                for k, f in freq.items():
                    if f == min_freq:
                        min_freq_key = k
                        break
                if min_freq_key is not None:
                    del cache[min_freq_key]
                    del freq[min_freq_key]
            cache[key] = result
            freq[key] = 1
            min_freq = 1
            return result

        return wrapper
    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    if not self._data:
        raise KeyError('dictionary is empty')
    key, value = next(iter(self._data.items()))
    del self._data[key]
    return (key, value)

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    if key in self:
        return self[key]
    else:
        self[key] = default
        return default

def get(self, key, default=None):
        """
        D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
        """
        if key in self:
            return self[key]
        else:
            return default

