def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == 0:
        return {}
    result = {}
    for key, value in d1.items():
        if key not in d2:
            result[key] = value
        elif isinstance(value, dict) and isinstance(d2[key], dict):
            if level == -1:
                sub_diff = difference(value, d2[key], level)
            else:
                sub_diff = difference(value, d2[key], level - 1)
            if sub_diff:
                result[key] = sub_diff
        elif value != d2[key]:
            result[key] = value
    return result

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    errors = []
    for key, value in labels.items():
        # Validate key
        if not isinstance(key, str):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            if not re.match(r'^[a-zA-Z0-9_]+$', key):
                errors.append({key: f"Label key '{key}' does not match the regex ^[a-zA-Z0-9_]+$"})

        # Validate value
        if not isinstance(value, str):
            errors.append({str(value): 'expected string or bytes-like object'})
        else:
            if not re.match(r'^[a-zA-Z0-9_\-\.]+$', value):
                errors.append({value: f"Label value '{value}' does not match the regex ^[a-zA-Z0-9_\\-\\.]+$"})

    if errors:
        raise ValidationError(messages=errors)

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    if self.status == 'valid':
        return prefix + 'Valid'
    elif self.status == 'invalid':
        return prefix + 'Invalid'
    else:
        return prefix + 'Unknown'

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    if not hasattr(self, 'log') or self.log is None:
        return prefix + "No validation log available."

    # Assuming self.log is a list of strings or objects with a string representation
    log_entries = []
    for entry in self.log:
        log_entries.append(str(entry))

    if not log_entries:
        return prefix + "Validation log is empty."

    # Join all log entries with newlines and prepend the prefix
    return prefix + "\n".join(log_entries)

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not isinstance(inventory, dict):
        raise ArgumentError("inventory", "Expected a dict, but got `%s`" % type(inventory).__name__)

    if extract_spec_version:
        type_value = inventory.get('type')
        if type_value is not None:
            try:
                self.spec_version = self._extract_spec_version_from_type(type_value)
            except (ValueError, KeyError):
                # If extraction fails, fall back to the existing self.spec_version
                pass

    # Perform validation based on the current self.spec_version
    # This is a placeholder for the actual validation logic which would depend on
    # the specific schema and version.
    # For the purpose of this generation, we assume a basic structure check.
    if 'items' not in inventory:
        raise ArgumentError("inventory", "Missing required field 'items'")

    if not isinstance(inventory['items'], list):
        raise ArgumentError("inventory.items", "Expected a list, but got `%s`" % type(inventory['items']).__name__)

    return inventory

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    for manifest_file in manifest_files:
        for digest in manifest_file.digests:
            if digest not in digests_used:
                raise ValueError(f"Digest {digest} in manifest file {manifest_file} is not used")

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator object")

    # Check that the prior inventory is a subset of the current inventory
    # This means that all items in the prior inventory must be present in the current inventory
    # and the quantities in the prior inventory must be less than or equal to the quantities in the current inventory
    for item, quantity in prior.inventory.items():
        if item not in self.inventory:
            raise ValueError(f"Item {item} in prior inventory is not present in the current inventory")
        if quantity > self.inventory[item]:
            raise ValueError(f"Quantity of item {item} in prior inventory ({quantity}) is greater than in the current inventory ({self.inventory[item]})")

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if version not in inventory:
        raise ValueError(f"Version {version} not found in inventory")

    version_data = inventory[version]
    if not isinstance(version_data, dict):
        raise TypeError(f"Inventory data for version {version} must be a dictionary")

    logical_path_map = {}
    for logical_path, file_info in version_data.items():
        if not isinstance(file_info, (list, tuple, set)):
            file_info = [file_info]
        logical_path_map[logical_path] = set(file_info)

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    if 'files' not in fixity:
        raise ValueError("Fixity block must contain a 'files' key")

    files = fixity['files']
    if not isinstance(files, list):
        raise ValueError("Fixity 'files' must be a list")

    for file_entry in files:
        if not isinstance(file_entry, dict):
            raise ValueError("Each file entry in fixity must be a dictionary")

        if 'path' not in file_entry:
            raise ValueError("Each file entry in fixity must contain a 'path' key")

        file_path = file_entry['path']
        if file_path not in manifest_files:
            raise ValueError(f"File '{file_path}' in fixity is not listed in the manifest")

def files_list(path):
    """
    Return the files in `path`
    """
    try:
        return [f for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))]
    except OSError:
        return []

