def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`
    """
    if not isinstance(content, str):
        raise TypeError("Content must be a string")
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    for xpath in pubdate_xpaths:
        try:
            result = node.xpath(xpath)
            if result:
                return result[0]
        except Exception:
            continue
    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    if not hasattr(self, '__dict__'):
        return str(self)

    lines = []
    prefix = "  " * indent
    lines.append(prefix + self.__class__.__name__ + " {")

    for key, value in self.__dict__.items():
        if key.startswith('_'):
            continue
        if hasattr(value, 'pretty'):
            value_str = value.pretty(indent=indent + 1, debug=debug)
        else:
            value_str = repr(value)
        lines.append(prefix + "  " + key + ": " + value_str)

    lines.append(prefix + "}")
    return "\n".join(lines)

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from sympy.logic.boolalg import And, Or, Not
    from sympy import S

    def _absorb(expr):
        if isinstance(expr, And):
            args = list(expr.args)
            new_args = []
            for i, a in enumerate(args):
                for j, b in enumerate(args):
                    if i == j:
                        continue
                    if isinstance(b, Or):
                        b_args = list(b.args)
                        if a in b_args:
                            # A & (A | B) = A
                            return a
                        if Not(a) in b_args:
                            # A & (~A | B) = A & B
                            b_args.remove(Not(a))
                            if len(b_args) == 1:
                                b = b_args[0]
                            else:
                                b = Or(*b_args)
                            args[j] = b
                            break
            return And(*args)
        elif isinstance(expr, Or):
            args = list(expr.args)
            new_args = []
            for i, a in enumerate(args):
                for j, b in enumerate(args):
                    if i == j:
                        continue
                    if isinstance(b, And):
                        b_args = list(b.args)
                        if a in b_args:
                            # A | (A & B) = A
                            return a
                        if Not(a) in b_args:
                            # A | (~A & B) = A | B
                            b_args.remove(Not(a))
                            if len(b_args) == 1:
                                b = b_args[0]
                            else:
                                b = And(*b_args)
                            args[j] = b
                            break
            return Or(*args)
        else:
            return expr

    return [_absorb(arg) for arg in args]

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner_func(*args, **kwargs):
        if sys.version_info[0] >= 3:
            return namefunc(*args, **kwargs)
        else:
            return namefunc(*args, **kwargs).encode()
    return inner_func

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        import importlib.metadata
        try:
            version = importlib.metadata.version("package_name")
            return version
        except importlib.metadata.PackageNotFoundError:
            return "unknown"
    except ImportError:
        try:
            import pkg_resources
            try:
                version = pkg_resources.get_distribution("package_name").version
                return version
            except pkg_resources.DistributionNotFound:
                return "unknown"
        except ImportError:
            return "unknown"

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if pieces["error"]:
        return {"error": pieces["error"], "version": pieces["error"]}

    if style == "pep440":
        rendered = render_pep440(pieces)
    elif style == "pep440-pre":
        rendered = render_pep440_pre(pieces)
    elif style == "pep440-post":
        rendered = render_pep440_post(pieces)
    elif style == "pep440-old":
        rendered = render_pep440_old(pieces)
    elif style == "git-describe":
        rendered = render_git_describe(pieces)
    elif style == "git-describe-long":
        rendered = render_git_describe_long(pieces)
    else:
        raise ValueError("unknown style '%s'" % style)

    return dict(rendered, **pieces)

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    if any(p.startswith("dev") or p.startswith("rc") for p in pieces):
        return "+"
    else:
        return "."

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    # Build the full command list
    cmd = list(commands) + list(args)

    # Prepare environment
    if env is None:
        env = os.environ.copy()
    else:
        env = os.environ.copy()
        env.update(env)

    # Determine whether to capture stderr
    stderr = subprocess.DEVNULL if hide_stderr else None

    # Run the command
    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr,
            check=True
        )
        if verbose:
            print("Command executed successfully:", ' '.join(cmd))
        return result
    except subprocess.CalledProcessError as e:
        if verbose:
            print("Command failed with return code", e.returncode)
            if e.stdout:
                print("stdout:", e.stdout.decode())
            if e.stderr and not hide_stderr:
                print("stderr:", e.stderr.decode())
        raise
    except Exception as e:
        if verbose:
            print("An error occurred while running the command:", str(e))
        raise

def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    def decorate(f):
        """Store f in HANDLERS[vcs][method]."""
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = f
        return f
    return decorate

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    try:
        # Traverse the storage root hierarchy
        for obj in self._traverse_hierarchy():
            num_objects += 1
            is_valid = True
            if validate_objects:
                is_valid = self._validate_object(obj)
            if check_digests and is_valid:
                is_valid = self._check_digest(obj)
            if is_valid:
                good_objects += 1
            elif show_warnings:
                self._warn(f"Invalid object: {obj}")
    except Exception as e:
        if show_warnings:
            self._warn(f"Error during hierarchy validation: {e}")
    return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    if not os.path.exists(self.path):
        os.makedirs(self.path)
    with open(os.path.join(self.path, 'ocfl_version'), 'w') as f:
        f.write('1.0')

def amend_bzparams(self, params, bug_ids):
        """Amend the Bugzilla params"""
        if not isinstance(params, dict):
            raise TypeError("params must be a dictionary")
        if not isinstance(bug_ids, (list, tuple)):
            raise TypeError("bug_ids must be a list or tuple")

        # Ensure all bug_ids are integers
        for bug_id in bug_ids:
            if not isinstance(bug_id, int):
                raise TypeError("All bug_ids must be integers")

        # Create a copy of the params to avoid modifying the original
        amended_params = params.copy()

        # Add the bug_ids to the params
        amended_params['id'] = bug_ids

        return amended_params

def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    """
    merged = {}
    for key, value in nodes:
        if key in merged:
            if isinstance(merged[key], MappingNode) and isinstance(value, MappingNode):
                merged[key].value = deep_merge_nodes(merged[key].value + value.value)
            else:
                merged[key] = value
        else:
            merged[key] = value
    return list(merged.items())

