def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number == 0:
        result = alphabet[0]
    else:
        result = ""
        base = len(alphabet)
        while number > 0:
            number, remainder = divmod(number, base)
            result = alphabet[remainder] + result
    if padding is not None and len(result) < padding:
        result = alphabet[0] * (padding - len(result)) + result
    return result

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError("value must be a string")
    if not isinstance(arg, str):
        raise TypeError("arg must be a string")
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    result = set()
    queue = set([cls])
    while queue:
        current = queue.pop()
        for sub in current.__subclasses__():
            if sub not in result:
                result.add(sub)
                queue.add(sub)
    result.discard(cls)
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    base = len(alphabet)
    inverse_alphabet = {char: idx for idx, char in enumerate(alphabet)}
    result = 0
    for char in string:
        if char not in inverse_alphabet:
            raise ValueError(f"Character {char!r} not in alphabet")
        result = result * base + inverse_alphabet[char]
    return result

def unquote(name):
    """Remove quote from the given name."""
    if name and len(name) >= 2:
        if (name[0] == name[-1]) and (name[0] in ('"', "'", '`', '<', '>')):
            return name[1:-1]
    return name

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        result = subprocess.run(['git', 'ls-files', '--others', '--ignored', '--exclude-standard'], capture_output=True, text=True, check=True)
        files = result.stdout.splitlines()
        ignored_files = [f for f in files if f in ignored]
        ignored_files.sort()
        return ','.join(ignored_files)
    except subprocess.CalledProcessError as e:
        raise Exception(f"Git command failed: {e.stderr}")

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency == "always":
        return None
    try:
        parts = frequency.split()
        if len(parts) != 2:
            raise ValueError("Invalid frequency format")
        number, unit = parts
        number = int(number)
        if unit == "second" or unit == "seconds":
            return datetime.timedelta(seconds=number)
        elif unit == "minute" or unit == "minutes":
            return datetime.timedelta(minutes=number)
        elif unit == "hour" or unit == "hours":
            return datetime.timedelta(hours=number)
        elif unit == "day" or unit == "days":
            return datetime.timedelta(days=number)
        elif unit == "week" or unit == "weeks":
            return datetime.timedelta(weeks=number)
        else:
            raise ValueError("Invalid time unit")
    except ValueError as e:
        raise ValueError(f"Invalid frequency: {frequency}")

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    if isinstance(matcher, str):
        name = matcher
        default = None
    elif isinstance(matcher, tuple) and len(matcher) == 2:
        name, default = matcher
    else:
        raise ValueError("matcher must be a string or a tuple of (name, default)")

    value = os.environ.get(name)
    if value is None:
        if default is not None:
            return default
        raise EnvironmentError(f"Environment variable '{name}' is not set and no default value provided")
    return value

