def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    configs = {}
    errors = []
    for filename in config_filenames:
        try:
            with open(filename, 'r') as f:
                config = yaml.safe_load(f)
            if config is None:
                config = {}
            if not isinstance(config, dict):
                raise ValueError(f"Configuration file {filename} must contain a dictionary")
            if overrides:
                config.update(overrides)
            if resolve_env:
                config = _resolve_env_vars(config)
            configs[filename] = config
        except Exception as e:
            log_record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=__file__,
                lineno=0,
                msg=f"Error loading configuration file {filename}: {str(e)}",
                args=None,
                exc_info=None
            )
            errors.append(log_record)
    return configs, errors

def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple or None")

        handlers = {}
        for name, obj in inspect.getmembers(cls):
            if inspect.isclass(obj) and issubclass(obj, cls) and obj is not cls:
                if hasattr(obj, 'protocol_version'):
                    version = obj.protocol_version
                    if protocol_version is None or version == protocol_version:
                        handlers[version] = obj
        return handlers

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    bookmarks = []
    for value in values:
        if not isinstance(value, str):
            raise TypeError("Each value must be a string")
        bookmarks.append(value)
    return cls(bookmarks)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, (list, tuple)):
        return seq, type(seq)
    elif isinstance(seq, (str, bytes)):
        return seq, type(seq)
    else:
        # If it's not a standard sequence type, try to convert it to a list
        try:
            seq_list = list(seq)
            return seq_list, list
        except TypeError:
            # If it's not iterable, return it as is with its type
            return seq, type(seq)

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    if not tentative:
        if not iface.providedBy(candidate):
            raise Invalid(
                "%r does not provide %r" % (candidate, iface)
            )

    errors = []

    for name in iface:
        element = iface[name]
        if isinstance(element, Method):
            # Check if the candidate has the method
            if not hasattr(candidate, name):
                errors.append(
                    "%r does not define %r" % (candidate, name)
                )
            else:
                # Check the signature
                try:
                    _checkSignature(element, getattr(candidate, name))
                except Invalid as e:
                    errors.append(str(e))
        else:
            # It's an Attribute
            if not hasattr(candidate, name):
                errors.append(
                    "%r does not define %r" % (candidate, name)
                )

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(iface, type):
        raise TypeError("iface must be a type")
    if not isinstance(candidate, type):
        raise TypeError("candidate must be a type")

    # Check if candidate is a subclass of iface
    if not issubclass(candidate, iface):
        raise TypeError("candidate is not a subclass of iface")

    # If tentative is False, we need to check that all abstract methods are implemented
    if not tentative:
        # Get all abstract methods from iface and its bases
        abstract_methods = set()
        for base in iface.__mro__:
            for name, value in vars(base).items():
                if getattr(value, '__isabstractmethod__', False):
                    abstract_methods.add(name)

        # Check if candidate implements all abstract methods
        for method_name in abstract_methods:
            if not hasattr(candidate, method_name):
                raise TypeError("candidate does not implement abstract method %s" % method_name)
            elif getattr(getattr(candidate, method_name), '__isabstractmethod__', False):
                raise TypeError("candidate does not implement abstract method %s" % method_name)

    return True

def pop(self, key, default=__marker):
        """
        D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
        If key is not found, d is returned if given, otherwise KeyError is raised.
        """
        if key in self:
            return self._data.pop(key)
        elif default is not __marker:
            return default
        else:
            raise KeyError(key)

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self._cache:
        raise KeyError('cache is empty')
    key, value = self._cache.popitem(last=False)
    return (key, value)

def popitem(self):
        """Remove and return the `(key, value)` pair least recently used."""
        if not self._cache:
            raise KeyError('cache is empty')
        key, value = next(iter(self._cache.items()))
        del self._cache[key]
        return (key, value)

def popitem(self):
        """Remove and return the `(key, value)` pair most recently used."""
        if not self._cache:
            raise KeyError('cache is empty')
        key, value = self._cache.popitem()
        return (key, value)

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    try:
        key = random.choice(list(self.keys()))
        value = self.pop(key)
        return (key, value)
    except IndexError:
        raise KeyError('dictionary is empty')

def _create_in_regex(self) -> Pattern:
    """
    Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    return re.compile(r'^\s*in\s*\(.*\)\s*$', re.IGNORECASE)

def _create_converter(self) -> _converting._Converter:
    """
    Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    return _converting._Converter(self._parameter_style)

def isoparse(self, dt_str):
    if isinstance(dt_str, bytes):
        dt_str = dt_str.decode('ascii')
    if not isinstance(dt_str, str):
        raise TypeError('isoparse() argument must be str or bytes, not %s' % type(dt_str).__name__)
    if len(dt_str) == 0:
        raise ValueError('isoparse() argument must not be empty')
    # Split the string into date and time parts
    if 'T' in dt_str:
        date_str, time_str = dt_str.split('T', 1)
    elif ' ' in dt_str:
        date_str, time_str = dt_str.split(' ', 1)
    else:
        date_str = dt_str
        time_str = None
    # Parse the date part
    date_obj = self._parse_date(date_str)
    # Parse the time part if present
    if time_str is not None:
        time_obj = self._parse_time(time_str)
    else:
        time_obj = None
    # Combine date and time
    if time_obj is not None:
        dt = datetime.datetime.combine(date_obj, time_obj)
    else:
        dt = datetime.datetime(date_obj.year, date_obj.month, date_obj.day)
    return dt

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Private encrypted JSON payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass
    # Public XML payload
    try:
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass
    return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    return dt.strftime("%Y-%m-%dT%H:%M:%S.%f")

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        return False
    if not tag:
        return False
    if tag.startswith('-') or tag.startswith('+'):
        return False
    if any(c.isspace() for c in tag):
        return False
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    for child in node:
        tag = child.tag
        if tag in result:
            if not isinstance(result[tag], list):
                result[tag] = [result[tag]]
            result[tag].append(child)
        else:
            result[tag] = child
    return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        data = json.loads(document)
        if "links" in data:
            return data
    except (json.JSONDecodeError, TypeError):
        pass
    try:
        root = ElementTree.fromstring(document)
        links = []
        for link in root.findall(".//{urn:xmpp:webfinger:1.0}link"):
            link_dict = {}
            for attr, value in link.attrib.items():
                link_dict[attr] = value
            links.append(link_dict)
        return {"links": links}
    except ElementTree.ParseError:
        pass
    return {}

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        host = handle.split("@")[1]
    except (AttributeError, IndexError):
        return None

    try:
        url = "https://{}/.well-known/webfinger?resource=acct:{}".format(host, quote(handle))
        response = requests.get(url, timeout=10)
        if response.status_code == 200:
            return response.text
        else:
            return None
    except Exception:
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    logger.debug("send_document: url=%s, data=%s, timeout=%s, method=%s", url, data, timeout, method)
    headers = CaseInsensitiveDict({
        'User-Agent': USER_AGENT,
    })
    if "headers" in kwargs:
        # Update from kwargs
        headers.update(kwargs.get("headers"))
    kwargs.update({
        "data": data, "timeout": timeout, "headers": headers
    })
    try:
        if method.lower() == "post":
            response = requests.post(url, *args, **kwargs)
        elif method.lower() == "get":
            response = requests.get(url, *args, **kwargs)
        else:
            raise ValueError(f"Unsupported method: {method}")
        logger.debug("send_document: response status code %s", response.status_code)
        return response.status_code, None
    except RequestException as ex:
        logger.debug("send_document: exception %s", ex)
        return None, ex

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    try:
        if not isinstance(settings_dirs, (list, tuple)):
            settings_dirs = [settings_dirs]

        file_names = []
        for directory in settings_dirs:
            if os.path.isdir(directory):
                for fname in os.listdir(directory):
                    if fname.endswith(spec_option):
                        file_names.append(os.path.join(directory, fname))

        return sorted(file_names)
    except (TypeError, OSError):
        return []

