def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("spec_content is required")

    try:
        data = yaml.safe_load(spec_content)
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Invalid YAML content: {e}")

    if not isinstance(data, dict):
        raise IRValidatorException("Spec content must be a dictionary")

    required_fields = ['name', 'version', 'description']
    for field in required_fields:
        if field not in data:
            raise IRValidatorException(f"Missing required field: {field}")

    return data

def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise IRValidatorException("yaml_file parameter is required")

        try:
            with open(yaml_file, 'r') as f:
                data = yaml.safe_load(f)
        except Exception as e:
            raise IRValidatorException(f"Failed to load YAML file: {str(e)}")

        if not isinstance(data, dict):
            raise IRValidatorException("YAML file must contain a dictionary")

        # Validate required fields
        required_fields = ['name', 'version']  # Example required fields
        for field in required_fields:
            if field not in data:
                raise IRValidatorException(f"Missing required field: {field}")

        return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if 'include' in parser_dict:
        include = parser_dict.pop('include')
        if isinstance(include, str):
            include = [include]
        for include_path in include:
            include_dict = self._load_spec(include_path)
            self._include_groups(include_dict)
            parser_dict.update(include_dict)

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            raise errors.InvalidSchemeError('Unable to build default for non-Option type')
        if not isinstance(arg.default, NoDefault):
            defaults[arg.name] = arg.default
        if isinstance(arg, DictOption):
            if arg.scheme:
                b = arg.scheme.build_defaults()
                if b:
                    defaults[arg.name] = b
    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    deprecated_args = {}
    for option in self.options:
        if option.deprecated:
            deprecated_args[option.name] = option.deprecated
    return deprecated_args

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    deprecated_args = []
    for arg in cli_args:
        if arg in self.deprecated_args:
            deprecated_args.append(arg)
    for arg in answer_file_args:
        if arg in self.deprecated_args:
            deprecated_args.append(arg)
    if deprecated_args:
        print("Warning: The following arguments are deprecated: " + ", ".join(deprecated_args))

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if not hasattr(self, 'parsers') or not isinstance(self.parsers, dict):
        return []

    parser = self.parsers.get(command_name)
    if parser is None:
        return []

    try:
        # In argparse, options are stored in _actions
        # We filter out the 'help' action and any positional arguments (which have no option strings)
        options = []
        for action in parser._actions:
            # Skip the help action
            if action.dest == 'help':
                continue
            # Skip positional arguments (they don't have option strings)
            if not action.option_strings:
                continue
            # Add the option strings to the list
            options.extend(action.option_strings)
        return options
    except Exception:
        return []

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    if command_name not in self._command_specs:
        raise KeyError("Unknown command: %s" % command_name)
    if argument_name not in self._command_specs[command_name]:
        raise KeyError("Unknown argument: %s for command: %s" % (argument_name, command_name))
    return self._command_specs[command_name][argument_name]

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent_args = []
    if args is None:
        return silent_args
    for arg in args:
        if hasattr(arg, 'silent') and arg.silent:
            silent_args.append(arg.dest)
    return silent_args

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    for arg in self.requires:
        if arg not in args:
            raise ValueError("Missing required argument: {}".format(arg))

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required_args = []
    for option in options_spec:
        if 'required_when' in option:
            condition = option['required_when']
            if isinstance(condition, str):
                if condition == command_name:
                    required_args.append(option['name'])
            elif isinstance(condition, (list, tuple)):
                if command_name in condition:
                    required_args.append(option['name'])
    return required_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg_name, arg_value in args.items():
        if isinstance(arg_value, str):
            max_length = self._get_max_length(arg_name)
            if max_length is not None and len(arg_value) > max_length:
                raise ValueError(
                    f"Argument '{arg_name}' value length {len(arg_value)} exceeds maximum allowed length {max_length}"
                )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg_name, arg_value in args.items():
        if arg_name in self.choices:
            if arg_value not in self.choices[arg_name]:
                raise ValueError(
                    "Invalid value '{}' for argument '{}'. "
                    "Allowed choices: {}".format(
                        arg_value, arg_name, self.choices[arg_name]
                    )
                )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    for arg in args:
        if arg < self.min_value or arg > self.max_value:
            raise ValueError(
                "Argument {} is out of range [{} - {}]".format(
                    arg, self.min_value, self.max_value
                )
            )

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    for arg in args:
        if arg.startswith('--'):
            key, value = arg[2:].split('=', 1)
            if key in self._control_args:
                control_args[key] = value
            else:
                nested_args[key] = value
        else:
            # Handle positional arguments or other formats if necessary
            # For now, assume all args are in --key=value format
            pass

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if extra_vars is None:
            return vars_dict

        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dictionary")

        if not isinstance(extra_vars, list):
            raise TypeError("extra_vars must be a list")

        for item in extra_vars:
            if isinstance(item, dict):
                vars_dict.update(item)
            elif isinstance(item, str):
                # Handle string items, possibly in key=value format
                if '=' in item:
                    key, value = item.split('=', 1)
                    vars_dict[key.strip()] = value.strip()
                else:
                    # If no '=' found, treat the whole string as a key with empty value
                    vars_dict[item.strip()] = ""
            else:
                # For other types, ignore or handle as needed
                pass

        return vars_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    spec_file = os.path.join(plugin_dir, 'plugin.json')
    if not os.path.exists(spec_file):
        raise FileNotFoundError(f"Plugin spec file not found: {spec_file}")

    with open(spec_file, 'r') as f:
        spec = json.load(f)

    def flatten_dict(d, parent_key='', sep='.'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    return flatten_dict(spec)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if 'CONFIG_PATH' not in os.environ:
        os.environ['CONFIG_PATH'] = self.config_path

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise ValueError("Path does not start with root: {} does not start with {}".format(path, root))
    return path[len(root):]
